"""Parse the first access-request field block in an RFC 822 message.

Anything after a ``-- `` signature separator is ignored. Sender display names
are not identities; requests carry the normalized mailbox address instead.
"""
from __future__ import annotations

import email
import re
from dataclasses import dataclass
from email import policy as email_policy
from email.utils import getaddresses
from pathlib import Path

TICKET_RE = re.compile(r"\[(AR-\d+)\]")
FIELD_RE = re.compile(r"^([A-Za-z-]+)\s*:\s*(.*)$")
ACTIONS = ("grant", "revoke")


class ParseError(ValueError):
    """An invalid request, retaining available metadata for the audit log."""

    def __init__(self, message: str):
        super().__init__(message)
        self.ticket = "?"
        self.msg_id = ""
        self.actor = ""


def sender_address(value: str) -> str:
    """Return one unambiguous mailbox, or an empty string for an invalid sender."""
    addresses = getaddresses([value])
    if len(addresses) != 1:
        return ""
    address = addresses[0][1].strip().lower()
    if address.count("@") != 1 or any(c.isspace() for c in address):
        return ""
    local, domain = address.split("@")
    return address if local and domain else ""


@dataclass
class Request:
    path: Path
    msg_id: str
    ticket: str
    sender: str
    action: str
    principal: str
    roles: list[str]
    justification: str = ""
    auth_failure: str = ""


def _plain_body(msg) -> str:
    part = msg.get_body(preferencelist=("plain",))
    if part is None or part.get_content_type() != "text/plain":
        raise ParseError("no text/plain part")
    try:
        return part.get_content()
    except (LookupError, UnicodeError, ValueError) as exc:
        raise ParseError(f"cannot decode text/plain body: {exc}") from exc


def parse_fields(text: str) -> dict[str, str]:
    fields: dict[str, str] = {}
    for line in text.splitlines():
        if line.rstrip() == "--":
            break
        m = FIELD_RE.match(line.strip())
        if m:
            fields.setdefault(m.group(1).lower(), m.group(2).strip())
    return fields


def _auth_failure(msg) -> str:
    # Only use the local receiving gateway's result, not a sender's assertion
    # or a quoted message body. Missing results are compatible with local mail.
    for value in msg.get_all("Authentication-Results", []):
        authority, _, results = str(value).partition(";")
        if authority.strip().lower() != "mx.fernhollow.dev":
            continue
        if re.search(r"(?:^|;)\s*dmarc\s*=\s*fail\b", results, re.IGNORECASE):
            return "sender authentication failed: receiving gateway reports dmarc=fail"
    return ""


def parse_message(path: Path) -> Request:
    with open(path, "rb") as fh:
        msg = email.message_from_binary_file(fh, policy=email_policy.default)
    subject = str(msg.get("Subject", ""))
    match = TICKET_RE.search(subject)
    ticket = match.group(1) if match else "?"
    msg_id = str(msg.get("Message-ID", "")).strip()
    from_headers = msg.get_all("From", [])
    sender = sender_address(str(from_headers[0])) if len(from_headers) == 1 else ""
    try:
        if not match:
            raise ParseError(f"no ticket id in subject {subject!r}")
        if not sender:
            raise ParseError("missing or ambiguous From address")
        fields = parse_fields(_plain_body(msg))
        action = fields.get("action", "").lower()
        if action not in ACTIONS:
            raise ParseError(f"unsupported action {action!r}")
        principal = fields.get("principal", "")
        if not principal:
            raise ParseError("missing Principal")
        if not fields.get("roles"):
            raise ParseError("missing Roles")
        roles = [role.strip() for role in fields["roles"].split(",")]
        if not all(roles):
            raise ParseError("empty role in Roles")
        return Request(
            path=path, msg_id=msg_id, ticket=ticket, sender=sender,
            action=action, principal=principal, roles=roles,
            justification=fields.get("justification", ""),
            auth_failure=_auth_failure(msg),
        )
    except ParseError as exc:
        exc.ticket, exc.msg_id, exc.actor = ticket, msg_id, sender
        raise
PY
